}

/**
 * Archiving an issue takes every live issue below it, at any depth, with it.
 * Processed parent-before-child so each descendant's own completion check
 * (see `maybeNotifyParentCompletion`) sees its direct parent as already
 * archived and stays silent, exactly like archiving a single sub-issue would.
 */
async function cascadeArchiveChildren(
  actor: Actor,
  orgId: OrgId,
  parent: Issue,
): Promise<void> {
  const children = await issueRepo.findChildren(orgId, parent.id);

  for (const child of children) {
    const wasOpen = !CLOSED_ISSUE_STATUSES.includes(child.status);
    const archivedChild = await issueRepo.archiveIssue(orgId, child.id);

    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archivedChild.id,
      projectId: archivedChild.projectId,
    });

    if (wasOpen) {
      await maybeNotifyParentCompletion(orgId, actor.userId, archivedChild);
    }

    await cascadeArchiveChildren(actor, orgId, archivedChild);
  }
}

/**
 * Setting, moving or clearing an issue's parent. Guards, in order: the issue
 * exists and is live, the new parent (if any) exists in the same project and
 * is live, the move does not create a cycle, and the move does not push the
 * issue's deepest descendant past `MAX_SUB_ISSUE_DEPTH`.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.parentId === input.parentId) return before;

  if (input.parentId !== null) {
    const parent = requireFound(
      await issueRepo.findIssueById(input.orgId, input.parentId),
      "Issue",
      input.parentId,
    );
    if (parent.projectId !== before.projectId) {
      throw new NotFoundError("Issue", input.parentId);
    }
    assertNotArchived("Issue", parent.id, parent);

    if (await isDescendantOrSelf(input.orgId, parent.id, before.id)) {
      throw new IssueHierarchyError(before.id, "cycle");
    }

    const parentLevel = await levelOf(input.orgId, parent.id);
    const height = await subtreeHeight(input.orgId, before.id);
    if (parentLevel + 1 + height > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(before.id, "too_deep");
    }
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct sub-issues, not archived, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.findChildren(orgId, issueId);
}

/** Counts over every non-archived issue below `issueId`, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return computeRollup(orgId, issueId);
}

async function computeRollup(orgId: OrgId, issueId: IssueId): Promise<IssueRollup> {
  const descendants = await collectDescendants(orgId, issueId, {});
  const open = descendants.filter(
    (descendant) => !CLOSED_ISSUE_STATUSES.includes(descendant.status),
  ).length;

  return { total: descendants.length, open, closed: descendants.length - open };
}

async function collectDescendants(
  orgId: OrgId,
  issueId: IssueId,
  scope: { includeArchived?: boolean },
): Promise<readonly Issue[]> {
  const children = await issueRepo.findChildren(orgId, issueId, scope);
  if (children.length === 0) return [];

  const nested = await Promise.all(
    children.map((child) => collectDescendants(orgId, child.id, scope)),
  );

  return [...children, ...nested.flat()];
}

/** Number of hops from `issueId` up to the root; a root issue is level 0. */
async function levelOf(orgId: OrgId, issueId: IssueId): Promise<number> {
  let level = 0;
  let current = await issueRepo.findIssueById(orgId, issueId);

  while (current?.parentId) {
    level += 1;
    current = await issueRepo.findIssueById(orgId, current.parentId);
  }

  return level;
}

/** Longest chain of parent→child links below `issueId`; 0 when it has no children. */
async function subtreeHeight(orgId: OrgId, issueId: IssueId): Promise<number> {
  const children = await issueRepo.findChildren(orgId, issueId, {
    includeArchived: true,
  });
  if (children.length === 0) return 0;

  const heights = await Promise.all(
    children.map((child) => subtreeHeight(orgId, child.id)),
  );

  return 1 + Math.max(...heights);
}

/** True when `targetId` is `candidateId` itself or one of its ancestors. */
async function isDescendantOrSelf(
  orgId: OrgId,
  candidateId: IssueId,
  targetId: IssueId,
): Promise<boolean> {
  let currentId: IssueId | null = candidateId;

  while (currentId !== null) {
    if (currentId === targetId) return true;
    const current = await issueRepo.findIssueById(orgId, currentId);
    currentId = current?.parentId ?? null;
  }

  return false;
}

/**
 * Fires `issue.sub_issues_completed` when a sub-issue that just stopped being
 * open was the last open issue below its direct parent. Silent when the
 * parent has no assignee, is archived, or has no sub-issues left to count.
 */
async function maybeNotifyParentCompletion(
  orgId: OrgId,
  actorId: UserId | null,
  closedChild: Issue,
): Promise<void> {
  if (closedChild.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, closedChild.parentId);
  if (parent === null || parent.archivedAt !== null) return;
  if (parent.assigneeId === null) return;

  const rollup = await computeRollup(orgId, parent.id);
  if (rollup.open > 0) return;

  await emit("issue.sub_issues_completed", {
    orgId,
    actorId,
    occurredAt: new Date().toISOString() as Issue["createdAt"],
    issueId: parent.id,
    projectId: parent.projectId,
    assigneeId: parent.assigneeId,
  });
}

